#[using="Type"] Lemma rpres_except_of_munch' : forall C W m m',
  munch W m m' -> wmono rsegs m m' ->
  (forall lo hi, In (lo, hi) W -> forall x, lo <= x < hi -> C x) ->
  rpres_except C m m'.
Proof.
