(* [comment removed for export] *)
Lemma rmrep_set_unmap_seq : forall st m i v,
  rmrep st m -> 0 <= i < 32 ->
  rmrep (upd_ctx (fun c => set_unmap_seq_map (<[i := v]> (c_unmap_seq c)) c) st) (write_to_mem m (wa (RCTX + 848 + i)) [b8 v]).
