  rmrep st m -> 0 <= c_meta_alloc_shift (ctx st) <= 40 ->
  let n := Z.shiftl 2 (c_meta_alloc_shift (ctx st)) in
  evt rsegs (fun ms' => ms' = MS (mkR (Z_to_bv 64 0xaf9a8) sp gp tp t0 t1 t2 (Z_to_bv 64 4096) (Z_to_bv 64 n)
